#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_common.h"
#include "MKXC144.h"

#define LED_PORT PORTE
#define LED_GPIO GPIOE
#define LED_PIN 24

// Simple software delay
static void delay(void)
{
    volatile uint32_t i;

    for (i = 0U; i < 500000U; ++i)
    {
        __asm("nop");
    }
}

int main(void)
{
    // Enable clock gate for PORTE and GPIOE
    CLOCK_EnableClock(kCLOCK_PortE);
    CLOCK_EnableClock(kCLOCK_GpioE);

    // Configure PTE24 as digital output
    port_pin_config_t port_config = {0};
    PORT_SetPinMux(LED_PORT, LED_PIN, kPORT_MuxAsGpio);

    // Initialize GPIO pin as output
    gpio_pin_config_t gpio_config = {
        .direction = kGPIO_DigitalOutput,
        .outputLogic = 0U,
        .interruptMode = kGPIO_NoIntmode
    };
    GPIO_PinInit(LED_GPIO, LED_PIN, &gpio_config);

    // Main loop: toggle LED
    while (1)
    {
        GPIO_PortToggle(GPIOE, 1U << LED_PIN);
        delay();
    }
}

