    port_pin_config_t i2cPinConfig = {
        .pullSelect = kPORT_PullUp,
        .slewRate = kPORT_SlowSlewRate,
        .driveStrength = kPORT_LowDriveStrength,
        .passiveFilterEnable = kPORT_PassiveFilterDisable,
        .openDrainEnable = kPORT_OpenDrainEnable,
    };
