    I2C_MasterTransferCreateHandle(I2C0, &g_i2cHandle, i2c_master_callback, NULL);

    // Send register address
    status_t status = I2C_MasterTransferNonBlocking(I2C0, &g_i2cHandle, &transfer);
    if (status != kStatus_Success)
    {
        while(1); // Transfer failed
    }

    // Wait for completion
    while (!g_i2cCompleted)
    {
    }

    // Now read the data
    g_i2cCompleted = false;
    transfer.direction = kI2C_Read;
    transfer.subaddressSize = 0; // No subaddress for read
    transfer.data = &g_i2cRxData;
    transfer.dataSize = 1;
    transfer.flags = kI2C_TransferDefaultFlag;

    status = I2C_MasterTransferNonBlocking(I2C0, &g_i2cHandle, &transfer);
    if (status != kStatus_Success)
    {
        while(1); // Read failed
    }

    // Wait for read to complete
    while (!g_i2cCompleted)
    {
    }

    // At this point, g_i2cRxData contains the WHO_AM_I value
    // Further processing...

    // Disable interrupts and spin
    I2C_DisableInterrupts(I2C0, kI2C_MasterInterruptEnable);
    while(1)
    {
    }
}

