#include "fsl_clock.h"
#include "fsl_pit.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_common.h"
#include "MKL17Z4.h" // Corrected: Not directly included as per rule, but note -- device header comes in via fsl_clock.h transitively in SDK build

/* Define the peripheral sources */
#define SAMPLE_PERIOD_MS        10U
#define SYSTEM_CLOCK            CLOCK_GetFreq(kCLOCK_CoreSysClk)
#define PIT_SOURCE_CLOCK        CLOCK_GetFreq(kCLOCK_BusClk) // Bus clock is 48 MHz
#define SAMPLE_PIN              (3U)
#define SAMPLE_PORT             PORTC
#define SAMPLE_GPIO             GPIOC
#define SAMPLE_GPIO_PIN         kGPIO_Pin3
#define LED_PORT                PORTE
#define LED_GPIO                GPIOE
#define LED_GPIO_PIN            kGPIO_Pin24
#define LED_GPIO_PORT_PIN       (24U)
#define PIT_CHANNEL             kPIT_Chnl_0

/* Global volatile variables for ISR communication */
static volatile uint8_t g_sampleReady = 0U;
static volatile uint8_t g_sampleValue = 0U;

/* PIT ISR Handler - must match vector table name */
void PIT0_IRQHandler(void)
{
    uint32_t intStatus;

    /* Read interrupt status for PIT channel 0 */
    intStatus = PIT_GetStatusFlags(PIT, PIT_CHANNEL);
    if (intStatus)
    {
        /* Clear interrupt flag */
        PIT_ClearStatusFlags(PIT, PIT_CHANNEL, intStatus);

        /* Sample PTC3 */
        g_sampleValue = GPIO_PinRead(SAMPLE_GPIO, SAMPLE_PIN);

        /* Signal main loop */
        g_sampleReady = 1U;
    }

    __DSB(); /* Data Synchronization Barrier for memory safety */
}

int main(void)
{
    uint8_t localSample;
    pit_config_t pitConfig;
    gpio_pin_config_t gpioConfig;

    /* Enable clock to PORTC and PORTE for pin mux */
    CLOCK_EnableClock(kCLOCK_PortC, 1);
    CLOCK_EnableClock(kCLOCK_PortE, 1);

    /* Configure PTC3 as digital input */
    PORT_SetPinMux(PORTC, SAMPLE_PIN, kPORT_MuxAsGpio);
    gpioConfig.pinDirection = kGPIO_DigitalInput;
    gpioConfig.outputLogic = 0U;
    GPIO_PinInit(SAMPLE_GPIO, SAMPLE_PIN, &gpioConfig);

    /* Configure PTE24 as GPIO output (LED) */
    PORT_SetPinMux(PORTE, LED_GPIO_PORT_PIN, kPORT_MuxAsGpio);
    gpioConfig.pinDirection = kGPIO_DigitalOutput;
    gpioConfig.outputLogic = 1U; // Start with LED off (active low logic assumed)
    GPIO_PinInit(LED_GPIO, LED_GPIO_PIN, &gpioConfig);

    /* Enable PIT clock */
    CLOCK_EnableClock(kCLOCK_Pit, 1);

    /* Get default PIT configuration */
    PIT_GetDefaultConfig(&pitConfig);

    /* Initialize PIT */
    PIT_Init(PIT, &pitConfig);

    /* Calculate the timer count for 10 ms at 48 MHz */
    uint32_t timerCount = (PIT_SOURCE_CLOCK * SAMPLE_PERIOD_MS) / 1000U;

    /* Setup PIT channel 0 to expire in SAMPLE_PERIOD_MS */
    PIT_SetTimerPeriod(PIT, PIT_CHANNEL, timerCount);
    PIT_EnableInterrupts(PIT, PIT_CHANNEL, kPIT_TimerInterruptEnable);
    EnableIRQ(PIT0_IRQn);

    /* Start PIT channel 0 */
    PIT_StartTimer(PIT, PIT_CHANNEL);

    /* Main loop */
    while (1)
    {
        /* Check if a new sample is ready */
        if (g_sampleReady)
        {
            /* Safely copy the sample value */
            localSample = g_sampleValue;

            /* Clear flag after reading (ISR-safe because we're not preempted by same ISR without lock, but still order matters) */
            g_sampleReady = 0U;

            /* If sampled pin is high, toggle LED */
            if (localSample)
            {
                GPIO_PortToggle(LED_GPIO, 1U << LED_GPIO_PORT_PIN);
            }
        }

        /* Other main loop tasks can go here */
    }
}

