#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"

// Define buffer size
#define BUFFER_SIZE 512

// Source and destination buffers
static uint8_t srcBuffer[BUFFER_SIZE];
static uint8_t dstBuffer[BUFFER_SIZE];
static volatile bool transferDone = false;

// eDMA transfer complete callback
void EDMA_Callback(edma_handle_t *handle, void *userData, bool transferDone, uint32_t tcds)
{
    if (transferDone)
    {
        *((volatile bool *)userData) = true;
    }
}

int main(void)
{
    edma_config_t edmaConfig;
    edma_transfer_config_t transferConfig;
    edma_handle_t edmaHandle;
    status_t status;
    uint32_t i;

    // Initialize source buffer with pattern: index & 0xFF
    for (i = 0; i < BUFFER_SIZE; i++)
    {
        srcBuffer[i] = (uint8_t)(i & 0xFFU);
    }

    // Clear destination buffer
    for (i = 0; i < BUFFER_SIZE; i++)
    {
        dstBuffer[i] = 0;
    }

    // Enable clock for DMA0
    CLOCK_EnableClock(kCLOCK_Dma0);

    // Get default eDMA configuration
    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(DMA0, &edmaConfig);

    // Create eDMA handle
    EDMA_CreateHandle(&edmaHandle, DMA0, 0U);  // Channel 0

    // Set callback
    EDMA_SetCallback(&edmaHandle, EDMA_Callback, (void *)&transferDone);

    // Prepare transfer configuration
    EDMA_PrepareTransfer(&transferConfig,
                         srcBuffer,                    // source address
                         sizeof(srcBuffer[0]),         // source offset bytes per request
                         dstBuffer,                    // destination address
                         sizeof(dstBuffer[0]),         // destination offset bytes per request
                         sizeof(srcBuffer[0]),         // bytes to transfer per request
                         BUFFER_SIZE,                  // total bytes to transfer
                         kEDMA_MemoryToMemory);         // transfer mode

    // Submit transfer
    status = EDMA_SubmitTransfer(&edmaHandle, &transferConfig);
    if (status != kStatus_Success)
    {
        while (1) {}  // Failed to submit transfer
    }

    // Start transfer
    EDMA_StartTransfer(&edmaHandle);

    // Wait for transfer to complete
    while (!transferDone)
    {
        __NOP();
    }

    // Compare source and destination buffers
    for (i = 0; i < BUFFER_SIZE; i++)
    {
        if (srcBuffer[i] != dstBuffer[i])
        {
            while (1) {}  // Mismatch found
        }
    }

    // Success: buffers match
    while (1) {}
}

