// Approximate 500ms software delay at ~600MHz (Cortex-M7)
// Calibrated for typical i.MX RT1176 M7 core speed; adjust if needed
void delay_ms(uint32_t ms)
{
    uint32_t count = ms * 240000U; // Approximate cycles per ms at 600 MHz
    while (count--)
    {
        __NOP();
    }
}

int main(void)
{
    // Enable clock for GPIO9
    CLOCK_EnableClock(kCLOCK_Gpio9);

    // Configure IOMUXC for GPIO_AD_04 as GPIO9[3]
    // GPIO_AD_04 is pad ID 36 on i.MX RT1176
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_04_GPIO9_IO03, 0U);

    // Configure pad settings (default push-pull output)
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_04_GPIO9_IO03,
                        IOMUXC_SW_PAD_CTL_PAD_PKE_MASK | // Enable pull
                        IOMUXC_SW_PAD_CTL_PAD_PUE_MASK | // Pull select (pull)
                        IOMUXC_SW_PAD_CTL_PAD_PUS(0U)  | // Pull up (100k)
                        IOMUXC_SW_PAD_CTL_PAD_HYS_MASK | // Hysteresis
                        IOMUXC_SW_PAD_CTL_PAD_DSE(6U)  | // Drive strength
                        IOMUXC_SW_PAD_CTL_PAD_SRE(0U));  // Slew rate

    // GPIO initialization: set direction to output
    gpio_pin_config_t led_config = {
        .pinDirection = kGPIO_DigitalOutput,
