    GPIO_PinWrite(LED_GPIO, LED_PIN, 0U);

    // Main loop: toggle LED every ~500 ms
    while (1)
    {
        GPIO_PinWrite(LED_GPIO, LED_PIN, 1U); // LED on
        delay_ms(500);
        GPIO_PinWrite(LED_GPIO, LED_PIN, 0U); // LED off
        delay_ms(500);
    }
}

