// Function to initialize LPI2C1 for communicating with I2C sensor
void init_i2c_sensor(void)
{
    lpi2c_master_config_t lpi2cConfig;
    status_t status;

    // Enable clock for LPI2C1
    CLOCK_EnableClock(kCLOCK_Lpi2c1);

    // Configure pin mux for LPI2C1 SCL (GPIO_AD_08) and SDA (GPIO_AD_09)
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_08_LPI2C1_SCL, 1U);
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_09_LPI2C1_SDA, 1U);

    // Configure LPI2C1 pins with pull-up and appropriate drive strength
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_08_LPI2C1_SCL, 
                        IOMUXC_SW_PAD_CTL_PAD_PUS(3) |     // 22k pull-up
                        IOMUXC_SW_PAD_CTL_PAD_HYS(1) |     // Hysteresis enabled
                        IOMUXC_SW_PAD_CTL_PAD_PUE(1) |     // Pull enable
