/*******************************************************************************
 * Definitions
 ******************************************************************************/
#define LPUART_BASEADDR LPUART1
#define LPUART_CLK_FREQ CLOCK_GetRootClockFreq(kCLOCK_Root_Lpuart1)
#define LPUART_RX_PIN GPIO_AD_25
#define LPUART_TX_PIN GPIO_AD_24
#define EXAMPLE_BAUDRATE 115200

/*******************************************************************************
 * Prototypes
 ******************************************************************************/
void BOARD_InitHardware(void);

/*******************************************************************************
 * Variables
 ******************************************************************************/
uint8_t rx_data;

/*******************************************************************************
 * Code
 ******************************************************************************/
void BOARD_InitHardware(void)
{
    /* Enable LPUART1 clock */
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    /* Configure LPUART1 TX and RX pins */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_LPUART1_TX, 0U);
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_LPUART1_RX, 0U);

    /* Set pin configuration for LPUART */
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_24_LPUART1_TX, 
                        IOMUXC_SW_PAD_CTL_PAD_PKE_MASK | 
                        IOMUXC_SW_PAD_CTL_PAD_SPEED(2) | 
                        IOMUXC_SW_PAD_CTL_PAD_DSE(6));
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_25_LPUART1_RX, 
                        IOMUXC_SW_PAD_CTL_PAD_PKE_MASK | 
                        IOMUXC_SW_PAD_CTL_PAD_SPEED(2) | 
                        IOMUXC_SW_PAD_CTL_PAD_DSE(6));
}

/*!
 * @brief Main function
 */
int main(void)
{
    lpuart_config_t config;

    /* Init board hardware */
    BOARD_InitHardware();

    /* Get default configuration for LPUART */
    LPUART_GetDefaultConfig(&config);
    config.baudRate_Bps = EXAMPLE_BAUDRATE;
    config.dataBits = kLPUART_EightDataBits;
    config.parityMode = kLPUART_ParityDisabled;
    config.stopBitCount = kLPUART_OneStopBit;
    config.enableTx = true;
    config.enableRx = true;

    /* Initialize LPUART */
    LPUART_Init(LPUART_BASEADDR, &config, LPUART_CLK_FREQ);

    /* Print welcome message */
    const char *welcome = "LPUART Echo Demo\r\n";
    LPUART_WriteBlocking(LPUART_BASEADDR, (uint8_t *)welcome, strlen(welcome));

    while (1)
    {
        /* Read one byte */
        LPUART_ReadBlocking(LPUART_BASEADDR, &rx_data, 1);

        /* Echo it back */
        LPUART_WriteBlocking(LPUART_BASEADDR, &rx_data, 1);
    }
}

